5	struct WalkTreePrefixProducer<'b, S, B> {
6	    to_explore: Vec<S>, // nodes (and subtrees) we have to process
7	    seen: Vec<S>,       // nodes which have already been explored
8	    children_of: &'b B, // function generating children
9	}
