11	impl<S, B, I> UnindexedProducer for WalkTreePrefixProducer<'_, S, B>
12	where
13	    S: Send,
14	    B: Fn(&S) -> I + Send + Sync,
15	    I: IntoIterator<Item = S, IntoIter: DoubleEndedIterator>,
16	{
17	    type Item = S;
18	
19	    fn split(mut self) -> (Self, Option<Self>) {
20	        // explore while front is of size one.
21	        while self.to_explore.len() == 1 {
22	            let front_node = self.to_explore.pop().unwrap();
23	            self.to_explore
24	                .extend((self.children_of)(&front_node).into_iter().rev());
25	            self.seen.push(front_node);
26	        }
27	        // now take half of the front.
28	        let right_children = split_vec(&mut self.to_explore);
29	        let right = right_children
30	            .map(|mut c| {
31	                std::mem::swap(&mut c, &mut self.to_explore);
32	                WalkTreePrefixProducer {
33	                    to_explore: c,
34	                    seen: Vec::new(),
35	                    children_of: self.children_of,
36	                }
37	            })
38	            .or_else(|| {
39	                // we can still try to divide 'seen'
40	                let right_seen = split_vec(&mut self.seen);
41	                right_seen.map(|s| WalkTreePrefixProducer {
42	                    to_explore: Default::default(),
43	                    seen: s,
44	                    children_of: self.children_of,
45	                })
46	            });
47	        (self, right)
48	    }
49	
50	    fn fold_with<F>(mut self, mut folder: F) -> F
51	    where
52	        F: Folder<Self::Item>,
53	    {
54	        // start by consuming everything seen
55	        folder = folder.consume_iter(self.seen);
56	        if folder.full() {
57	            return folder;
58	        }
59	        // now do all remaining explorations
60	        while let Some(e) = self.to_explore.pop() {
61	            self.to_explore
62	                .extend((self.children_of)(&e).into_iter().rev());
63	            folder = folder.consume(e);
64	            if folder.full() {
65	                return folder;
66	            }
67	        }
68	        folder
69	    }
70	}
