101	/// Create a tree-like prefix parallel iterator from an initial root node.
102	/// The `children_of` function should take a node and return an iterator over its child nodes.
103	/// The best parallelization is obtained when the tree is balanced
104	/// but we should also be able to handle harder cases.
105	///
106	/// # Ordering
107	///
108	/// This function guarantees a prefix ordering. See also [`walk_tree_postfix`],
109	/// which guarantees a postfix order.
110	/// If you don't care about ordering, you should use [`walk_tree`],
111	/// which will use whatever is believed to be fastest.
112	/// For example a perfect binary tree of 7 nodes will reduced in the following order:
113	///
114	/// ```text
115	///      a
116	///     / \
117	///    /   \
118	///   b     c
119	///  / \   / \
120	/// d   e f   g
121	///
122	/// reduced as a,b,d,e,c,f,g
123	///
124	/// ```
125	///
126	/// # Example
127	///
128	/// ```text
129	///      4
130	///     / \
131	///    /   \
132	///   2     3
133	///        / \
134	///       1   2
135	/// ```
136	///
137	/// ```
138	/// use rayon::iter::walk_tree_prefix;
139	/// use rayon::prelude::*;
140	///
141	/// let par_iter = walk_tree_prefix(4, |&e| {
142	///     if e <= 2 {
143	///         Vec::new()
144	///     } else {
145	///         vec![e / 2, e / 2 + 1]
146	///     }
147	/// });
148	/// assert_eq!(par_iter.sum::<u32>(), 12);
149	/// ```
150	///
151	/// # Example
152	///
153	/// ```
154	/// use rayon::prelude::*;
155	/// use rayon::iter::walk_tree_prefix;
156	///
157	/// struct Node {
158	///     content: u32,
159	///     left: Option<Box<Node>>,
160	///     right: Option<Box<Node>>,
161	/// }
162	///
163	/// // Here we loop on the following tree:
164	/// //
165	/// //       10
166	/// //      /  \
167	/// //     /    \
168	/// //    3     14
169	/// //            \
170	/// //             \
171	/// //              18
172	///
173	/// let root = Node {
174	///     content: 10,
175	///     left: Some(Box::new(Node {
176	///         content: 3,
177	///         left: None,
178	///         right: None,
179	///     })),
180	///     right: Some(Box::new(Node {
181	///         content: 14,
182	///         left: None,
183	///         right: Some(Box::new(Node {
184	///             content: 18,
185	///             left: None,
186	///             right: None,
187	///         })),
188	///     })),
189	/// };
190	///
191	/// let mut v: Vec<u32> = walk_tree_prefix(&root, |r| {
192	///     r.left
193	///         .as_ref()
194	///         .into_iter()
195	///         .chain(r.right.as_ref())
196	///         .map(|n| &**n)
197	/// })
198	/// .map(|node| node.content)
199	/// .collect();
200	/// assert_eq!(v, vec![10, 3, 14, 18]);
201	/// ```
202	///
203	pub fn walk_tree_prefix<S, B, I>(root: S, children_of: B) -> WalkTreePrefix<S, B>
204	where
205	    S: Send,
206	    B: Fn(&S) -> I + Send + Sync,
207	    I: IntoIterator<Item = S, IntoIter: DoubleEndedIterator>,
208	{
209	    WalkTreePrefix {
210	        initial_state: root,
211	        children_of,
212	    }
213	}
