218	struct WalkTreePostfixProducer<'b, S, B> {
219	    to_explore: Vec<S>, // nodes (and subtrees) we have to process
220	    seen: Vec<S>,       // nodes which have already been explored
221	    children_of: &'b B, // function generating children
222	}
223	
224	impl<S, B, I> UnindexedProducer for WalkTreePostfixProducer<'_, S, B>
225	where
226	    S: Send,
227	    B: Fn(&S) -> I + Send + Sync,
228	    I: IntoIterator<Item = S>,
229	{
230	    type Item = S;
231	
232	    fn split(mut self) -> (Self, Option<Self>) {
233	        // explore while front is of size one.
234	        while self.to_explore.len() == 1 {
235	            let front_node = self.to_explore.pop().unwrap();
236	            self.to_explore.extend((self.children_of)(&front_node));
237	            self.seen.push(front_node);
238	        }
239	        // now take half of the front.
240	        let right_children = split_vec(&mut self.to_explore);
241	        let right = right_children
242	            .map(|c| {
243	                let right_seen = std::mem::take(&mut self.seen); // postfix -> upper nodes are processed last
244	                WalkTreePostfixProducer {
245	                    to_explore: c,
246	                    seen: right_seen,
247	                    children_of: self.children_of,
248	                }
249	            })
250	            .or_else(|| {
251	                // we can still try to divide 'seen'
252	                let right_seen = split_vec(&mut self.seen);
253	                right_seen.map(|mut s| {
254	                    std::mem::swap(&mut self.seen, &mut s);
255	                    WalkTreePostfixProducer {
256	                        to_explore: Default::default(),
257	                        seen: s,
258	                        children_of: self.children_of,
259	                    }
260	                })
261	            });
262	        (self, right)
263	    }
264	
265	    fn fold_with<F>(self, mut folder: F) -> F
266	    where
267	        F: Folder<Self::Item>,
268	    {
269	        // now do all remaining explorations
270	        for e in self.to_explore {
271	            folder = consume_rec_postfix(&self.children_of, e, folder);
272	            if folder.full() {
273	                return folder;
274	            }
275	        }
276	        // end by consuming everything seen
277	        folder.consume_iter(self.seen.into_iter().rev())
278	    }
279	}
280	
281	fn consume_rec_postfix<F, S, B, I>(children_of: &B, s: S, mut folder: F) -> F
282	where
283	    F: Folder<S>,
284	    B: Fn(&S) -> I,
285	    I: IntoIterator<Item = S>,
286	{
287	    let children = (children_of)(&s).into_iter();
288	    for child in children {
289	        folder = consume_rec_postfix(children_of, child, folder);
290	        if folder.full() {
291	            return folder;
292	        }
293	    }
294	    folder.consume(s)
295	}
