326	/// Divide given vector in two equally sized vectors.
327	/// Return `None` if initial size is <=1.
328	/// We return the first half and keep the last half in `v`.
329	fn split_vec<T>(v: &mut Vec<T>) -> Option<Vec<T>> {
330	    if v.len() <= 1 {
331	        None
332	    } else {
333	        let n = v.len() / 2;
334	        Some(v.split_off(n))
335	    }
336	}
